# PowerShell completion for thronectl. Generated by 'thronectl completion powershell'.
# thronectl itself completes: 'thronectl __complete WORD... CURRENT' prints the candidates.

Register-ArgumentCompleter -Native -CommandName 'thronectl', 'thronectl.exe' -ScriptBlock {
    param($wordToComplete, $commandAst, $cursorPosition)

    $constant = [System.Management.Automation.Language.StringConstantExpressionAst]
    $expandable = [System.Management.Automation.Language.ExpandableStringExpressionAst]
    $variable = [System.Management.Automation.Language.VariableExpressionAst]
    $elements = $commandAst.CommandElements
    $prog = $elements[0].Extent.Text
    if ($elements[0] -is $constant) { $prog = $elements[0].Value }
    $app = Get-Command -Name $prog -CommandType Application -ErrorAction Ignore | Select-Object -First 1
    if (-not $app) { $app = Get-Command -Name thronectl -CommandType Application -ErrorAction Ignore | Select-Object -First 1 }
    if (-not $app) { return }

    # An argument as thronectl gets it: without its quotes, and with its variables expanded
    # when it holds nothing else, so that nothing such as "$(...)" runs.
    $unquote = {
        param($e)
        if ($e -is $constant) { return $e.Value }
        $text = $e.Extent.Text
        if ($e -is $variable) {
            $parts = @($e)
        } elseif ($e -is $expandable) {
            if ($e.StringConstantType -eq 'DoubleQuoted') { $text = $text.Substring(1, $text.Length - 2) }
            $parts = @($e.NestedExpressions)
        } else {
            return $text
        }
        foreach ($v in $parts) {
            if ($v -isnot $variable -or ($v.VariablePath.IsDriveQualified -and $v.VariablePath.DriveName -ne 'env')) { return $text }
        }
        try { $ExecutionContext.InvokeCommand.ExpandString($text) } catch { $text }
    }

    # The words before the cursor, and the one under it up to the cursor.
    $words = [System.Collections.Generic.List[string]]::new()
    $words.Add('__complete')
    $current = ''
    foreach ($e in $elements | Select-Object -Skip 1) {
        if ($e.Extent.StartOffset -ge $cursorPosition) { break }
        if ($e.Extent.EndOffset -ge $cursorPosition) {
            if ($e -is $constant -and $e.Extent.EndOffset -eq $cursorPosition) {
                $current = $e.Value
            } else {
                $current = $e.Extent.Text.Substring(0, $cursorPosition - $e.Extent.StartOffset) -replace '^[''"]', ''
            }
            break
        }
        $words.Add((& $unquote $e))
    }
    $words.Add($current)

    # Quoted as the Windows C runtime and .NET read a command line, on every platform.
    $arguments = foreach ($w in $words) {
        if ($w -ne '' -and $w -notmatch '[\s"]') { $w; continue }
        '"' + ($w -replace '(\\*)"', '$1$1\"' -replace '(\\+)$', '$1$1') + '"'
    }
    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $app.Path
    # Set-Location does not change the directory that a new process starts in.
    $psi.WorkingDirectory = (Get-Location -PSProvider FileSystem).ProviderPath
    $psi.Arguments = $arguments -join ' '
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $true
    $psi.RedirectStandardInput = $true
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    $psi.StandardOutputEncoding = New-Object System.Text.UTF8Encoding $false
    try {
        $p = [System.Diagnostics.Process]::Start($psi)
        $p.StandardInput.Close()
        $null = $p.StandardError.ReadToEndAsync()
        $out = $p.StandardOutput.ReadToEnd()
        $p.WaitForExit()
    } catch {
        return
    }

    $lines = @($out -split '\r?\n' | Where-Object { $_ -ne '' })
    $directive = 0
    if ($lines.Count -gt 0 -and $lines[-1] -match '^:(\d+)$') {
        $directive = [int]$Matches[1]
        $lines = @($lines | Select-Object -SkipLast 1)
    }
    # PowerShell may replace only the end of the word, such as the item after the last
    # comma of a list.
    $strip = 0
    if ($current.Length -gt $wordToComplete.Length -and $current.EndsWith($wordToComplete)) {
        $strip = $current.Length - $wordToComplete.Length
    }
    $results = [System.Collections.Generic.List[System.Management.Automation.CompletionResult]]::new()
    foreach ($line in $lines) {
        $text, $desc = $line -split '\t', 2
        if ($strip -gt 0) {
            if (-not $text.StartsWith($current.Substring(0, $strip))) { continue }
            $text = $text.Substring($strip)
        }
        if ($text -eq '') { continue }
        if (-not $desc) { $desc = $text }
        $completion = $text
        if ($text -match '[\s''"`$;(){}@|&<>]') { $completion = "'" + $text.Replace("'", "''") + "'" }
        $results.Add([System.Management.Automation.CompletionResult]::new($completion, $text, 'ParameterValue', $desc))
    }
    if ($directive -band 2) {
        $prefix = ''
        $file = $wordToComplete
        if ($file -match '^(-[^=]*=)(.*)$') {
            $prefix = $Matches[1]
            $file = $Matches[2]
        }
        foreach ($r in [System.Management.Automation.CompletionCompleters]::CompleteFilename($file)) {
            $results.Add([System.Management.Automation.CompletionResult]::new($prefix + $r.CompletionText, $r.ListItemText, $r.ResultType, $r.ToolTip))
        }
    }
    if ($results.Count -eq 0 -and -not ($directive -band 2)) {
        # Where thronectl has nothing, an empty string keeps PowerShell from completing file
        # names: CompleteInput throws on it, which PSReadLine takes as no completion.
        return ''
    }
    $results
}
